create table if not exists public.feed_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(trim(body)) between 1 and 500),tags text[] not null default '{}',created_at timestamptz not null default now());
create table if not exists public.feed_reactions(post_id uuid references public.feed_posts(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,kind text not null check(kind in ('like','insightful','celebrate','motivated')),primary key(post_id,user_id));
create table if not exists public.feed_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.feed_posts(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,parent_id uuid references public.feed_comments(id) on delete cascade,body text not null check(char_length(trim(body)) between 1 and 300),created_at timestamptz not null default now(),edited_at timestamptz);
create index if not exists feed_posts_newest on public.feed_posts(created_at desc);
create index if not exists feed_comments_post on public.feed_comments(post_id);
alter table public.feed_posts enable row level security;
alter table public.feed_reactions enable row level security;
alter table public.feed_comments enable row level security;
grant select,insert,delete on public.feed_posts to authenticated;
grant select,insert,update,delete on public.feed_reactions,public.feed_comments to authenticated;
drop policy if exists "feed posts read" on public.feed_posts;
create policy "feed posts read" on public.feed_posts for select to authenticated using(true);
drop policy if exists "feed posts create" on public.feed_posts;
create policy "feed posts create" on public.feed_posts for insert to authenticated with check(author_id=(select auth.uid()));
drop policy if exists "feed posts delete" on public.feed_posts;
create policy "feed posts delete" on public.feed_posts for delete to authenticated using(author_id=(select auth.uid()));
drop policy if exists "feed reactions read" on public.feed_reactions;
create policy "feed reactions read" on public.feed_reactions for select to authenticated using(true);
drop policy if exists "feed reactions insert" on public.feed_reactions;
create policy "feed reactions insert" on public.feed_reactions for insert to authenticated with check(user_id=(select auth.uid()));
drop policy if exists "feed reactions update" on public.feed_reactions;
create policy "feed reactions update" on public.feed_reactions for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
drop policy if exists "feed reactions delete" on public.feed_reactions;
create policy "feed reactions delete" on public.feed_reactions for delete to authenticated using(user_id=(select auth.uid()));
drop policy if exists "feed comments read" on public.feed_comments;
create policy "feed comments read" on public.feed_comments for select to authenticated using(true);
drop policy if exists "feed comments insert" on public.feed_comments;
create policy "feed comments insert" on public.feed_comments for insert to authenticated with check(author_id=(select auth.uid()) and (parent_id is null or exists(select 1 from public.feed_comments c where c.id=parent_id and c.post_id=feed_comments.post_id and c.parent_id is null)));
drop policy if exists "feed comments update" on public.feed_comments;
create policy "feed comments update" on public.feed_comments for update to authenticated using(author_id=(select auth.uid())) with check(author_id=(select auth.uid()));
drop policy if exists "feed comments delete" on public.feed_comments;
create policy "feed comments delete" on public.feed_comments for delete to authenticated using(author_id=(select auth.uid()) or exists(select 1 from public.feed_posts p where p.id=post_id and p.author_id=(select auth.uid())));
